from lib import *
S = SS('k43')
F1 = [['web-0', '+0.0 → Ready +7.0 s'], ['web-1', '+7.0 → Ready +14.0 s'], ['web-2', '+14.0 → Ready +21.0 s'], ['缩容', '先 web-2,5.8 s 后 web-1']]
F2 = [['web-0', 'IP 10.244.2.106'], ['删除重建', '名字不变,uid 变'], ['web-0', 'IP 10.244.2.107'], ['DNS', 'web-0.web… 跟着指向新 IP']]
F3 = [['data-web-0/1/2', '每个 Pod 一个 PVC'], ['删 Pod 重建', 'PVC / PV 不变,数据还在'], ['缩容', 'PVC 默认保留'], ['whenScaled: Delete', 'PVC 随 Pod 删除']]
F4 = [['OrderedReady', '只创建 ord-0'], ['Parallel', '3 个都创建'], ['ord-0 Ready', 'ord-1 才被创建']]
PANELS = [('f', 'flow', 'StatefulSet 的身份'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("StatefulSet web(3 副本,OrderedReady,就绪探针延迟 3 秒):web-0 创建于 +0.0 秒、Ready 于 +7.0 秒;web-1 在 web-0 Ready 的同一刻(+7.0 秒)才创建,Ready 于 +14.0 秒;web-2 创建于 +14.0 秒、Ready 于 +21.0 秒。缩到 1 个副本(Pod 要 5 秒才结束):web-2 在 +0.2 秒开始终止,web-1 在 +5.8 秒才开始——web-2 完全结束之后才轮到 web-1,从大序号往小序号逐个删。", f=fl(F1, cur=[0, 1, 2], mark=[3]), t=tl(S(1), mark=lidx(S(1), 'web-1:创建于', 'web-2:创建于', '缩到 1 个副本'), done=lidx(S(1), 'web-0:创建于')), kv=KV([['OrderedReady', '创建:前一个 Ready 才建下一个;删除:逆序,前一个没了才删下一个'], ['Pod 名字', '<名字>-<序号>,序号固定'], ['代价', '启动慢,整体耗时是各 Pod 之和']], ['OrderedReady'])),
    step("稳定的网络身份:web-0 的 hostname=web-0、Pod IP 10.244.2.106,DNS web-0.web.k43.svc.cluster.local → 10.244.2.106。删掉 web-0 重建后名字仍是 web-0、uid 变了、Pod IP 变成 10.244.2.107,同一个 DNS 名字跟着指向新 IP;headless Service web.k43.svc 返回全部 3 个 Pod 的 IP。", f=fl(F2, cur=[1, 3], done=[0, 2]), t=tl(S(2), mark=lidx(S(2), '删掉 web-0 重建之后'), done=lidx(S(2), 'web-0 的 Pod IP', 'headless')), kv=KV([['稳定的是名字', '不是 IP'], ['DNS', '<pod>.<headless service>.<ns>.svc 跟着 Pod 走'], ['客户端要用名字', '不要缓存 IP']], ['稳定的是名字'])),
    step("稳定的存储:volumeClaimTemplates 为每个 Pod 建一个 PVC(data-web-0/1/2,各 10Mi)。web-1 往 /data/note 写 hello-1,删掉 web-1 重建:/data/note 还是 hello-1,PVC 绑定的 PV 没变;缩到 1 个副本后 data-web-0/1/2 三个 PVC 都还在,扩回 3 个旧数据仍在。persistentVolumeClaimRetentionPolicy whenScaled: Delete 的 StatefulSet wd 缩到 1 个后 data-wd-1 随 Pod 被删;whenDeleted: Delete 时删除 StatefulSet 后 PVC 全部消失。", f=fl(F3, cur=[1, 3], done=[0], mark=[2]), t=tl(S(3), mark=lidx(S(3), '缩到 1 个副本之后 PVC', 'whenScaled: Delete'), done=lidx(S(3), '删掉 web-1 重建之后', '再扩回 3 个')), kv=KV([['PVC 与 Pod 序号绑定', 'Pod 重建后接回同一个 PVC'], ['默认保留', '缩容、删除 StatefulSet 都不删 PVC'], ['persistentVolumeClaimRetentionPolicy', '可以改成随缩容 / 随删除一起删']], ['默认保留'])),
    step("OrderedReady 会被一个不就绪的 Pod 卡住:就绪探针要求 /data/ready(没人创建),18 秒后 ord(OrderedReady)只创建了 ord-0;par(Parallel)3 个 Pod 全部创建;都没有 Ready。只给 ord-0 创建 /data/ready 后,ord-1 才被创建。", f=fl(F4, cur=[0], done=[1, 2]), t=tl(S(4), mark=lidx(S(4), 'ord(podManagementPolicy=OrderedReady)'), done=lidx(S(4), 'par(podManagementPolicy=Parallel)', '只给 ord-0')), kv=KV([['OrderedReady', '一个不就绪,后面的都不会创建'], ['Parallel', '一起创建,一起终止,不保证顺序'], ['数据库集群初始化', '通常需要有序;无状态的分片可以 Parallel']], ['OrderedReady'])),
]
A = mkartk('k43', 43, 'Kubernetes,StatefulSet,稳定身份,headless Service,volumeClaimTemplates,podManagementPolicy,真实验证,动画演示',
    '在 kind 集群里实测 StatefulSet 的三个“稳定”:Pod 按 web-0、web-1、web-2 有序创建(前一个 Ready 才创建下一个,各 7 秒)并从大序号往小序号逐个终止;重建后名字和 DNS(web-0.web.<ns>.svc)不变但 Pod IP 会变;volumeClaimTemplates 给每个 Pod 一个 PVC,Pod 重建和缩容扩容后数据仍在,persistentVolumeClaimRetentionPolicy 可让 PVC 随缩容/删除一起删除;OrderedReady 会被一个不就绪的 Pod 卡住,Parallel 不会。',
    'StatefulSet 比 Deployment 多了什么?Pod 的名字、DNS 和数据在重建后到底哪些不变?为什么有序创建会“卡住”?这篇用一个带 PVC 的 StatefulSet,把有序创建与终止、名字与 IP、存储与 PVC 的保留策略,以及 podManagementPolicy 的差别都实测一遍。',
    [('7 秒一个', 'OrderedReady 时 web-0、web-1、web-2 依次创建并 Ready 的间隔'), ('10.244.2.106 → .107', 'web-0 删除重建后 Pod IP 的变化,而名字与 DNS 名字不变'), ('ord-0 only', '没有 Pod 就绪时 OrderedReady 只创建了的 Pod(Parallel 创建了 3 个)')],
    [('有序创建,逆序终止', '<p><code>OrderedReady</code>(默认)下,web-0 创建于 +0.0 秒、Ready 于 +7.0 秒;web-1 在 web-0 Ready 的同一刻才创建,+14.0 秒 Ready;web-2 +14.0 创建、+21.0 秒 Ready。缩容反过来:web-2 先终止,等它<b>完全</b>结束(这里 Pod 要 5 秒),web-1 才在 +5.8 秒开始终止。需要按序号初始化、按序号下线的数据库集群靠的就是这个。</p>'),
     ('名字稳定,IP 不稳定', '<p>Pod 的名字是 <code>&lt;sts名&gt;-&lt;序号&gt;</code>,<code>hostname</code> 也是它,配合 headless Service 得到稳定的 DNS 名 <code>web-0.web.k43.svc.cluster.local</code>。删掉 web-0 重建:名字不变、uid 变了、Pod IP 从 10.244.2.106 变成 10.244.2.107,DNS 名字跟着解析到新 IP;<code>web.k43.svc</code> 本身返回所有 Pod 的 IP。所以客户端要用名字找成员,不能缓存 IP。</p>'),
     ('每个 Pod 一个 PVC', '<p><code>volumeClaimTemplates</code> 为每个 Pod 创建 <code>data-web-0</code>、<code>data-web-1</code>、<code>data-web-2</code>。web-1 在 <code>/data/note</code> 里写了 <code>hello-1</code>,删掉重建后文件还在,PVC 绑定的 PV 也没变;缩到 1 个副本之后三个 PVC 仍在,扩回 3 个旧数据依然在。默认的保留策略是为了不丢数据;设置 <code>persistentVolumeClaimRetentionPolicy: {whenScaled: Delete, whenDeleted: Delete}</code> 后,缩容时对应的 PVC 随 Pod 一起删除,删除 StatefulSet 时所有 PVC 也跟着没了。</p>'),
     ('被一个不就绪的 Pod 卡住', '<p>就绪探针要求一个没人创建的文件。<code>OrderedReady</code> 的 StatefulSet 18 秒后只创建了 <code>ord-0</code>(它不 Ready,后面的就不创建);<code>podManagementPolicy: Parallel</code> 的 3 个 Pod 同时创建。给 <code>ord-0</code> 创建了文件之后 <code>ord-1</code> 才出现。一个 Pod 起不来会让整个 StatefulSet 停在原地,排查时要先看序号最小的那个不就绪的 Pod。</p>')],
    steps,
    [ENV_K + '。独立的 5 节点 kind 集群 kx-sched(Kubernetes v1.37.0),存储是 kind 默认的 local-path StorageClass(standard);Pod 是 busybox:1.36,就绪探针 initialDelaySeconds=3;第 1 节的缩容用 terminationGracePeriodSeconds=5 让每个 Pod 的终止持续几秒(宽限期为 0 时两个 Pod 同时消失,看不出顺序);DNS 用同命名空间里一个 busybox Pod 的 nslookup;时间取自 Pod 的 creationTimestamp 与 Ready 条件的 lastTransitionTime,以及 0.1 秒间隔轮询;每种情形各一次',
     '没有验证:StatefulSet 更新策略(下一篇);volumeClaimTemplates 的存储类扩容;节点失联时 StatefulSet Pod 的强制删除与“至多一个”语义;minReadySeconds;ordinals.start(从非 0 序号开始);local-path 的卷绑定在某个节点上,Pod 重建后能否换到别的节点;Pod 的 podAntiAffinity 与 StatefulSet 的组合'],
    'StatefulSet 的身份', PANELS)
